RUN = re.compile(r'cold_run_\w+\.py')

def label(code, note=None):
    return '%s (%s)' % (code, note) if note else TEXT[code]

EXCEPTIONS = {}
for k, v in DEC.items():
    EXCEPTIONS[k] = label(*v) if isinstance(v, tuple) else label(v)

RELABEL = {}
DEFER = set()

def DEFAULT(uid, c):
    if uid.startswith('law02') and c['id'] in LAW02_L0: v = LAW02_L0[c['id']]; return label(*v) if isinstance(v, tuple) else label(v)
    if uid.startswith('law03') and c['id'] in LAW03_L0: v = LAW03_L0[c['id']]; return label(*v) if isinstance(v, tuple) else label(v)
    m = RUN.search(c.get('claim_en', ''))
    if m:  # a compiled-run row: the runner's name read from the claim by script (B1's convention)
        return "ink (the compiled run — %s; the answer sheet's rows as test data)" % m.group(0)
    return None
